            colors.setdefault(value, []).append((r, c))
    # Repeated colors mark straight line segments. Extend each segment in both
    # directions through the background, leaving all existing clues untouched.
    for color, points in colors.items():
        if color == 0 or len(points) < 2:
            continue
        for i, (r1, c1) in enumerate(points):
            for r2, c2 in points[i+1:]:
                dr, dc = r2-r1, c2-c1
                # Use the primitive step so that any aligned pair extends fully.
                import math
                g = math.gcd(abs(dr), abs(dc))
                if not g:
                    continue
                sr, sc = dr//g, dc//g
                # Only extend pairs in an aligned arrangement; intervening clues
                # are retained, and this also handles separated endpoints.
                r, c = r1-sr, c1-sc
                while 0 <= r < h and 0 <= c < w:
                    if out[r][c] == grid[r][c]:
                        # Background is the most frequent border value in ARC tasks.
                        bg = max(set(v for row in grid for v in row), key=lambda v: sum(x == v for row in grid for x in row))
