    flat = [v for row in grid for v in row]
    background = max(set(flat), key=flat.count)
    out = [row[:] for row in grid]

    # Continue diagonal rays wherever two same-colored clue cells are adjacent.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr, dc in [(-1, -1), (-1, 1), (1, -1), (1, 1)]:
                nr, nc = r + dr, c + dc
                if not (0 <= nr < h and 0 <= nc < w) or grid[nr][nc] != color:
                    continue
                for sr, sc, ar, ac in [(-dr, -dc, r, c), (dr, dc, nr, nc)]:
                    rr, cc = ar + sr, ac + sc
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == background:
                        out[rr][cc] = color
                        rr += sr
                        cc += sc
    return out

